a, b = map(int, input().split())
def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True
ps = [x for x in range(a, b + 1) if is_prime(x)]
print(" ".join(map(str, ps)) if ps else "None")

